// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

/**
 * @title EmailNotificationOracle
 * @notice Manages email notification requests via oracle pattern.
 *         A reverse proxy validates external requests before they reach
 *         the off-chain oracle worker that processes SendEmail events.
 */
contract EmailNotificationOracle is Ownable {
    using Strings for uint256;

    struct EmailRequest {
        address requester;
        string recipient;
        string callbackEndpoint;
        uint256 timestamp;
        bool processed;
    }

    mapping(uint256 => EmailRequest) public requests;
    uint256 public requestCounter;

    // Trusted relay addresses (set by owner)
    mapping(address => bool) public trustedRelays;

    // Allowed callback domain hashes for SSRF prevention
    mapping(bytes32 => bool) public allowedCallbackDomains;

    // Internal network CIDR markers (stored as prefix hashes)
    mapping(bytes32 => bool) private internalNetworkPrefixes;

    event SendEmail(
        uint256 indexed requestId,
        string recipient,
        string callbackEndpoint,
        address indexed requester
    );

    event CallbackRegistered(uint256 indexed requestId, string endpoint);

    constructor() Ownable() {
        // Register known internal prefixes to block
        internalNetworkPrefixes[keccak256("http://127.")] = true;
        internalNetworkPrefixes[keccak256("http://10.")] = true;
        internalNetworkPrefixes[keccak256("http://172.16.")] = true;
        internalNetworkPrefixes[keccak256("http://192.168.")] = true;
        internalNetworkPrefixes[keccak256("http://169.254.")] = true;
        internalNetworkPrefixes[keccak256("http://localhost")] = true;
        internalNetworkPrefixes[keccak256("https://127.")] = true;
        internalNetworkPrefixes[keccak256("https://10.")] = true;
        internalNetworkPrefixes[keccak256("https://172.16.")] = true;
        internalNetworkPrefixes[keccak256("https://192.168.")] = true;
        internalNetworkPrefixes[keccak256("https://localhost")] = true;
    }

    function addTrustedRelay(address relay) external onlyOwner {
        trustedRelays[relay] = true;
    }

    function addAllowedDomain(string calldata domain) external onlyOwner {
        allowedCallbackDomains[keccak256(bytes(domain))] = true;
    }

    /**
     * @notice Validates that a callback URL doesn't target internal networks.
     * @dev Uses prefix matching against known internal network patterns.
     *      The oracle worker behind the reverse proxy uses this to determine
     *      if the callback is safe to invoke.
     */
    function _validateCallbackNotInternal(string memory url) internal view returns (bool) {
        bytes memory urlBytes = bytes(url);
        if (urlBytes.length < 8) return false;

        // Extract varying length prefixes and check against blocked list
        // Check prefixes of length 12 to 20 characters
        for (uint i = 12; i <= 20 && i <= urlBytes.length; i++) {
            bytes memory prefix = new bytes(i);
            for (uint j = 0; j < i; j++) {
                prefix[j] = urlBytes[j];
            }
            if (internalNetworkPrefixes[keccak256(prefix)]) {
                return false;
            }
        }
        return true;
    }

    /**
     * @notice Extracts domain from URL for allowlist checking.
     * @dev Parses the domain portion between :// and the next / or end.
     */
    function _extractDomain(string memory url) internal pure returns (string memory) {
        bytes memory urlBytes = bytes(url);
        uint start = 0;

        // Find :// (guard against underflow when the URL is shorter than 3 bytes)
        if (urlBytes.length >= 3) {
            for (uint i = 0; i <= urlBytes.length - 3; i++) {
                if (urlBytes[i] == 0x3a && urlBytes[i+1] == 0x2f && urlBytes[i+2] == 0x2f) {
                    start = i + 3;
                    break;
                }
            }
        }

        // Find end of domain (next / or : for port, or end of string)
        uint end = urlBytes.length;
        for (uint i = start; i < urlBytes.length; i++) {
            if (urlBytes[i] == 0x2f || urlBytes[i] == 0x3a) {
                end = i;
                break;
            }
        }

        bytes memory domain = new bytes(end - start);
        for (uint i = start; i < end; i++) {
            domain[i - start] = urlBytes[i];
        }
        return string(domain);
    }

    /**
     * @notice Submit an email notification request with a callback URL.
     * @dev The callback URL is where the oracle posts delivery confirmation.
     *      Validation ensures no SSRF against internal services.
     * @param recipient The email address to send to
     * @param callbackEndpoint URL for delivery status callback
     */
    function requestEmailWithCallback(
        string calldata recipient,
        string calldata callbackEndpoint
    ) external returns (uint256) {
        require(bytes(recipient).length > 0, "Empty recipient");
        require(bytes(callbackEndpoint).length > 0, "Empty callback");

        // SSRF validation: block internal network targets
        require(
            _validateCallbackNotInternal(callbackEndpoint),
            "Callback targets internal network"
        );

        // Domain allowlist check
        string memory domain = _extractDomain(callbackEndpoint);
        require(
            allowedCallbackDomains[keccak256(bytes(domain))],
            "Callback domain not in allowlist"
        );

        uint256 requestId = requestCounter++;
        requests[requestId] = EmailRequest({
            requester: msg.sender,
            recipient: recipient,
            callbackEndpoint: callbackEndpoint,
            timestamp: block.timestamp,
            processed: false
        });

        emit SendEmail(requestId, recipient, callbackEndpoint, msg.sender);
        emit CallbackRegistered(requestId, callbackEndpoint);

        return requestId;
    }

    /**
     * @notice Trusted relay can submit on behalf of users (from reverse proxy)
     * @dev The reverse proxy authenticates users and forwards via trusted relay.
     *      Even relay requests must pass full validation including domain allowlist.
     */
    function relayEmailRequest(
        address onBehalfOf,
        string calldata recipient,
        string calldata callbackEndpoint
    ) external returns (uint256) {
        require(trustedRelays[msg.sender], "Not a trusted relay");
        require(bytes(recipient).length > 0, "Empty recipient");
        require(bytes(callbackEndpoint).length > 0, "Empty callback");

        // Full SSRF validation on the raw URL as-is (no normalization)
        require(
            _validateCallbackNotInternal(callbackEndpoint),
            "Callback targets internal network"
        );

        // Domain allowlist check - same as direct requests
        string memory domain = _extractDomain(callbackEndpoint);
        require(
            allowedCallbackDomains[keccak256(bytes(domain))],
            "Callback domain not in allowlist"
        );

        uint256 requestId = requestCounter++;
        requests[requestId] = EmailRequest({
            requester: onBehalfOf,
            recipient: recipient,
            callbackEndpoint: callbackEndpoint,
            timestamp: block.timestamp,
            processed: false
        });

        emit SendEmail(requestId, recipient, callbackEndpoint, onBehalfOf);
        emit CallbackRegistered(requestId, callbackEndpoint);

        return requestId;
    }

    function markProcessed(uint256 requestId) external {
        require(trustedRelays[msg.sender], "Not authorized");
        requests[requestId].processed = true;
    }
}
